import assert from 'node:assert/strict';
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import test from 'node:test';
import { expectedCases, writerCases, validateReceipt, validateGoEvents, validateManifest, validateRemoteTranscript, reviewResourcesMySQL, reviewLocalRecheck, localRecheckPins, localRecheckEnvironment, legacyWindows936Name } from './d-resources-mysql-actual-review-20261023.mjs';

// All remote text below is synthetic parser input. No remote run or accepted
// actual-MySQL receipt is generated by this test file.
const hash = text => crypto.createHash('sha256').update(text).digest('hex');
const binary = hash('synthetic probe');
const migration = hash('synthetic migration');
const inputs = hash('synthetic inputs');
const catalog = hash('synthetic catalog');
const owner = path.resolve('.tmp-d-index-cache-' + 'a'.repeat(32));
const fixtureReceipt = () => ({
  kind: 'd_resources_mysql_preparation.v1', suite: 'readback', remote_requested: true,
  error: null, owner, owner_removed: true, remote_scratch_removed: true,
  dependencies_installed: false, synthetic_proofs: true, production_approved: false,
  binary_sha256: binary, migration_binary_sha256: migration, inputs_sha256: inputs,
  steps: [
    ['go', 'test', '-count=1', '-timeout=180s', '-json', './internal/systembackupresources'],
    ['go', 'test', '-tags', 'systembackup_mysql', '-run', '^TestDResources(Readback|Write)MySQLSeed$', '-count=1', '-json', './internal/systembackupresources'],
    ['go', 'test', '-c', '-tags', 'systembackup_mysql', '-o', path.join(owner, 'bundle/d-resources-readback.test'), './internal/systembackupresources'],
    ['go', 'build', '-o', path.join(owner, 'bundle/system-backup-migrate'), './cmd/system-backup-migrate'],
  ].map((command, index) => ({ command, exit_code: 0, platform: index < 2 ? 'windows' : 'linux', log_sha256: hash('synthetic log ' + index) })),
});
const namespace = 'sbk-mig-261023140000-abcd';
const uid = 'aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee';
const probe = 'TestDResourcesReadbackMySQL';
const fixtureText = () => [
  `RUN namespace=${namespace} uid=${uid} app_image=example@sha256:${binary} mysql_image=mysql:8.4 mysql_version=8.4.6`,
  `PASS pinned-migration-runner binary_sha256=${migration} catalog_sha256=${catalog}`,
  'PASS fresh-migration-replay=001..096 applied=96 exact_filenames=yes d_columns=blob/blob/blob/char',
  `=== RUN   ${probe}`,
  '    restore_readback_mysql_test.go:310: RESOURCES_FIXTURE mysql=8.4.6 migrations=96 tables=44 clone=LIKE foreign_key_proof=no synthetic_registry=yes',
  ...expectedCases.flatMap(name => [`=== RUN   ${probe}/${name}`, `    --- PASS: ${probe}/${name} (0.01s)`]),
  '    restore_readback_mysql_test.go:427: PASS resources-readback-mysql cases=12 five_normalizers=yes nine_storage_tables=yes controls=35 synthetic_proofs=yes foreign_key_proof=no ddl_freeze_proof=no production=no',
  '    restore_readback_mysql_test.go:211: CLEANED resources-mysql-owned-database-and-user=yes',
  `--- PASS: ${probe} (1.00s)`,
  'PASS',
  `PASS d-resources-readback-mysql cases=12 binary_sha256=${binary} inputs_sha256=${inputs} synthetic_proofs=yes full_restore=no production=no`,
  `CLEANED namespace=${namespace} uid=${uid}`,
  'CLEANED resources-remote-scratch=yes',
  `CLEANED resources-local-owner=${owner} removed=True`,
].join('\n');
const checkText = text => validateRemoteTranscript(text, fixtureReceipt(), { migrationCount: 96, lastMigration: '096', catalogHash: catalog });
const writerText = () => {
  const lines = fixtureText().replaceAll(probe, 'TestDResourcesWriteMySQL').split('\n').filter(line => !line.includes('TestDResourcesWriteMySQL/'));
  lines.splice(lines.findIndex(line => line.includes('RESOURCES_FIXTURE')) + 1, 0,
    ...writerCases.flatMap(name => [`=== RUN   TestDResourcesWriteMySQL/${name}`, `    --- PASS: TestDResourcesWriteMySQL/${name} (0.01s)`]));
  return lines.join('\n').replace('PASS resources-readback-mysql cases=12 five_normalizers=yes nine_storage_tables=yes controls=35', 'PASS resources-write-mysql cases=9 tables=9 independent_select_only=yes')
    .replace('PASS d-resources-readback-mysql cases=12', 'PASS d-resources-write-mysql cases=9');
};

// Native go test -v reports completed children after the parent summary.
const deferredText = text => {
  const lines = text.split('\n');
  const children = lines.filter(line => /^\s+--- PASS: TestDResources(?:Readback|Write)MySQL\//.test(line));
  const result = lines.filter(line => !children.includes(line));
  result.splice(result.indexOf('PASS'), 0, ...children);
  return result.join('\n');
};

for (const suite of ['readback', 'writer']) test('native deferred child PASS summaries: ' + suite, () => {
  const receipt = { ...fixtureReceipt(), suite };
  const text = deferredText(suite === 'writer' ? writerText() : fixtureText());
  const options = { migrationCount: 96, lastMigration: '096', catalogHash: catalog };
  const check = candidate => validateRemoteTranscript(candidate, receipt, options);
  assert.equal(check(text).remote_cases, suite === 'writer' ? 9 : 12);
  const childPass = text.split('\n').find(line => /^\s+--- PASS: Test.*MySQL\//.test(line));
  const childRun = text.split('\n').find(line => /^=== RUN   Test.*MySQL\//.test(line));
  const moveBefore = (line, anchor) => {
    const lines = text.split('\n').filter(item => item !== line);
    lines.splice(lines.indexOf(anchor), 0, line);
    return lines.join('\n');
  };
  assert.throws(() => check(text.replace(childPass + '\n', '') + '\n' + childPass), /case pass outside probe/);
  assert.throws(() => check(moveBefore(childRun, 'PASS')), /case start outside probe|remote case pass before start/);
  assert.throws(() => check(moveBefore(childPass, text.split('\n').find(line => line.startsWith('--- PASS: Test')))), /case pass outside probe/);
  assert.throws(() => check(text.replace(childPass, childPass.replace('--- PASS:', '--- SKIP:'))));
});
test('writer nine cases have their own root, summary and receipt scope', () => {
  const receipt = { ...fixtureReceipt(), suite: 'writer' };
  validateReceipt(receipt, { suite: 'writer' });
  const options = { migrationCount: 96, lastMigration: '096', catalogHash: catalog };
  assert.equal(validateRemoteTranscript(writerText(), receipt, options).remote_cases, 9);
  assert.throws(() => validateRemoteTranscript(writerText(), fixtureReceipt(), options));
  assert.throws(() => validateRemoteTranscript(fixtureText(), receipt, options));
  for (const name of writerCases) {
    const missing = writerText().split('\n').filter(line => !line.includes('/' + name)).join('\n');
    assert.throws(() => validateRemoteTranscript(missing, receipt, options), 'missing writer case ' + name);
  }
});

test('synthetic complete transcript passes only the parser; CRLF and BOM supported', () => {
  const result = checkText('\uFEFF' + fixtureText().replaceAll('\n', '\r\n'));
  assert.deepEqual(result, { namespace, namespace_uid: uid, remote_cases: 12 });
});

const transcriptMutations = {
  'one case missing': text => text.split('\n').filter(line => !line.includes('/null_is_not_empty')).join('\n'),
  'duplicate case pass': text => text + '\n    --- PASS: TestDResourcesReadbackMySQL/null_is_not_empty (0.01s)',
  'case skipped': text => text.replace('--- PASS: TestDResourcesReadbackMySQL/null_is_not_empty', '--- SKIP: TestDResourcesReadbackMySQL/null_is_not_empty'),
  'case failed': text => text.replace('--- PASS: TestDResourcesReadbackMySQL/null_is_not_empty', '--- FAIL: TestDResourcesReadbackMySQL/null_is_not_empty'),
  'wrong case despite same count': text => text.replaceAll('/null_is_not_empty', '/some_other_case'),
  'no actual root': text => text.replace(`=== RUN   ${probe}\n`, ''),
  'local JSON encoded PASS cannot replace raw root': text => text.replace(`--- PASS: ${probe} (1.00s)`, JSON.stringify({ Action: 'output', Output: `--- PASS: ${probe} (1.00s)\n` })),
  'root failed after case passes': text => text.replace(`--- PASS: ${probe} (1.00s)`, `--- FAIL: ${probe} (1.00s)`),
  'root omitted': text => text.replace(`--- PASS: ${probe} (1.00s)\n`, ''),
  'native completion omitted': text => text.replace('\nPASS\n', '\n'),
  'mixed writer root': text => text + '\n=== RUN   TestDResourcesWriteMySQL',
  'wrong probe binary': text => text.replace(`cases=12 binary_sha256=${binary}`, `cases=12 binary_sha256=${inputs}`),
  'wrong input capsule': text => text.replace(`inputs_sha256=${inputs}`, `inputs_sha256=${binary}`),
  'wrong migration binary': text => text.replace(`runner binary_sha256=${migration}`, `runner binary_sha256=${binary}`),
  'wrong catalog': text => text.replace(`catalog_sha256=${catalog}`, `catalog_sha256=${binary}`),
  'partial migrations': text => text.replace('applied=96', 'applied=95'),
  'older migration filename': text => text.replace('001..096', '001..095'),
  'different fixture ledger': text => text.replace('migrations=96 tables=44', 'migrations=95 tables=44'),
  'wrong MySQL version': text => text.replaceAll('mysql=8.4.6', 'mysql=8.0.6'),
  'missing database cleanup': text => text.replace(/^.*CLEANED resources-mysql-owned-database-and-user=yes\n/m, ''),
  'pending cleanup': text => text + '\nCLEANUP_PENDING remote=/tmp/example',
  'UID changed cleanup skipped': text => text + '\nCLEANUP_SKIPPED namespace UID changed',
  'wrong namespace UID': text => text.replace(`CLEANED namespace=${namespace} uid=${uid}`, `CLEANED namespace=${namespace} uid=${'b'.repeat(36)}`),
  'wrong cleanup namespace': text => text.replace(`CLEANED namespace=${namespace}`, `CLEANED namespace=sbk-mig-261023140001-abcd`),
  'missing scratch cleanup': text => text.replace('CLEANED resources-remote-scratch=yes\n', ''),
  'missing owner cleanup': text => text.replace(/^CLEANED resources-local-owner=.*$/m, ''),
  'wrong local owner': text => text.replace('resources-local-owner=' + owner, 'resources-local-owner=' + owner + '-other'),
  'cleanup before phase completion': text => {
    const lines = text.split('\n'); const index = lines.findIndex(line => line.startsWith('CLEANED namespace='));
    const [cleanup] = lines.splice(index, 1); lines.unshift(cleanup); return lines.join('\n');
  },
  'duplicate run identities': text => text.split('\n')[0] + '\n' + text,
  'case pass before start': text => text.replace(`=== RUN   ${probe}/null_is_not_empty\n    --- PASS: ${probe}/null_is_not_empty (0.01s)`, `    --- PASS: ${probe}/null_is_not_empty (0.01s)\n=== RUN   ${probe}/null_is_not_empty`),
  'truncated after remote success': text => text.slice(0, text.indexOf('CLEANED namespace=')),
};
for (const [name, mutate] of Object.entries(transcriptMutations)) {
  test('reject synthetic transcript: ' + name, () => assert.throws(() => checkText(mutate(fixtureText()))));
}

test('valid native metadata alone does not qualify remote evidence', () => validateReceipt(fixtureReceipt()));
