  const receipt = fixtureReceipt();
  receipt.steps[1].command[5] = '^Test(DResources(Readback|Write)|AResourcesWriteFK)MySQLSeed$';
  validateReceipt(receipt);
  receipt.steps[1].command[5] = '^TestDResourcesReadbackMySQLSeed$';
