for (const suite of ['readback', 'writer']) test('synthetic file-level receipt binds its logs, source, and cleanup; fixture files are removed: ' + suite, () => {
  const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
  const scratch = fs.mkdtempSync(path.join(root, 'docs/evidence/.tmp-d-receiver-unit-'));
  const marker = crypto.randomUUID();
  fs.writeFileSync(path.join(scratch, 'owner.txt'), marker);
  const prefix = path.join(scratch, 'd-resources-mysql-20000101-000000-aaaaaaaa');
  const read = name => fs.readFileSync(path.join(root, name));
  const writeJSON = (file, value) => fs.writeFileSync(file, JSON.stringify(value));
  try {
    const selected = [
      'backend/go.mod', 'backend/go.sum', 'backend/internal/systembackupcontroller/bootstrap.go',
      'scripts/system-backup-d-resources-mysql-validation.ps1', 'scripts/system-backup-d-resources-readback-phase.sh',
      'scripts/system-backup-d-resources-mysql-inputs.mjs', 'scripts/system-backup-d-index-source-snapshot.ps1',
      'scripts/system-backup-a-config-proof-source.ps1', 'scripts/system-backup-fresh-migration-smoke.sh',
      'scripts/system-backup-smoke-contract.sh', 'scripts/system-backup-d-invariants-phase.sh', 'scripts/system-backup-d-migration-phase.sh',
    ];
    for (const dir of ['backend/internal/systembackupresources', 'backend/internal/db/migrations', 'backend/cmd/system-backup-migrate', 'contracts']) {
      selected.push(...fs.readdirSync(path.join(root, dir), { recursive: true, withFileTypes: true }).filter(entry => entry.isFile()).map(entry => path.relative(root, path.join(entry.parentPath, entry.name)).replaceAll('\\', '/')).filter(name => /\.(go|json|sql)$/.test(name)));
    }
    const pins = [...new Set(selected)].sort().map(name => ({ path: name, size: read(name).length, sha256: hash(read(name)) }));
    const manifest = { kind: 'd_index_group_source_snapshot', version: 1, files: pins, source_sha256: hash(pins.map(pin => `${pin.path}\0${pin.sha256}\0${pin.size}`).join('\n') + '\n') };
    validateManifest(manifest);
    writeJSON(prefix + '-source.json', manifest);
    const receipt = fixtureReceipt(); receipt.source = prefix + '-source.json'; receipt.suite = suite;
    const inputBytes = read('backend/internal/systembackupresources/testdata/restore-readback-mysql-inputs.json');
    receipt.inputs_sha256 = hash(inputBytes);
    const ordinaryLog = read(suite === 'writer' ? 'docs/evidence/a-writer-fk-20261023-134215-75d1f525-fixed.jsonl' : 'docs/evidence/d-resources-rules-local-a7788a3e6b8a474db6fb5bb667aa36cd.jsonl').toString('utf8').replace(/^\uFEFF/, '').trim().split(/\r?\n/).map(line => ({ ...JSON.parse(line), Package: pkg })).map(event => JSON.stringify(event)).join('\n');
    const seedNames = ['TestDResourcesReadbackMySQLSeed', 'TestDResourcesWriteMySQLSeed'];
    if (suite === 'writer') { seedNames.unshift('TestAResourcesWriteFKMySQLSeed'); receipt.steps[1].command[5] = '^Test(DResources(Readback|Write)|AResourcesWriteFK)MySQLSeed$'; }
    const seeds = eventText([{ Action: 'start', Package: pkg }, ...seedNames.flatMap(Test => [{ Action: 'run', Test, Package: pkg }, { Action: 'pass', Test, Package: pkg }]), { Action: 'pass', Package: pkg }]);
    for (let index = 0; index < 4; index++) {
      const log = `${prefix}-step-${index}.jsonl`; const bytes = index === 0 ? ordinaryLog : index === 1 ? seeds : '';
      fs.writeFileSync(log, bytes); receipt.steps[index].log = log; receipt.steps[index].log_sha256 = hash(bytes);
    }
    writeJSON(prefix + '.json', receipt);
    const actualCatalog = /ContractMigrationCatalogHash\s*=\s*"([a-f0-9]{64})"/.exec(read('backend/internal/systembackupcontroller/bootstrap.go').toString())[1];
    const actualMigrations = JSON.parse(inputBytes).migrations;
    const text = (suite === 'writer' ? writerText() : fixtureText()).replace(`inputs_sha256=${inputs}`, `inputs_sha256=${receipt.inputs_sha256}`).replace(`catalog_sha256=${catalog}`, `catalog_sha256=${actualCatalog}`).replace('001..096', '001..' + actualMigrations.at(-1).name.split('_')[0]).replace('applied=96', 'applied=' + actualMigrations.length).replace('migrations=96 tables=44', `migrations=${actualMigrations.length} tables=44`);
    fs.writeFileSync(prefix + '.txt', text);
    const result = reviewResourcesMySQL(prefix + '.json');
    assert.equal(result.remote_cases, suite === 'writer' ? 9 : 12); assert.equal(result.old_pass_events_preserved, suite === 'writer' ? 843 : 678);
    assert.equal(result.scope, suite === 'writer' ? 'isolated_synthetic_writer_only' : 'isolated_synthetic_readback_only');
    assert.equal(result.production_approved, false); assert.equal(result.remote_cleanup_independently_queried, false);
    assert.equal(result.artifacts.length, 8); // receipt, manifest, four steps, baseline, transcript

    const recheckPrefix = path.join(scratch, 'd-resources-local-recheck-' + 'b'.repeat(32));
    fs.writeFileSync(recheckPrefix + '.jsonl', ordinaryLog);
    fs.writeFileSync(recheckPrefix + '.stderr.txt', '');
    const rel = file => path.relative(root, file).replaceAll('\\', '/');
    const makeSupplement = () => ({
      kind: 'd_resources_local_recheck.v1', parent_receipt: { path: rel(prefix + '.json'), sha256: hash(fs.readFileSync(prefix + '.json')) },
      source_manifest: { path: rel(prefix + '-source.json'), sha256: hash(fs.readFileSync(prefix + '-source.json')) },
      inputs: localRecheckPins(manifest), command: receipt.steps[0].command, environment: localRecheckEnvironment,
      exit_code: 0, error: null, owner: path.join(root, '.tmp-d-resources-recheck-' + 'b'.repeat(32)),
      owner_removed: true, source_verified_before_and_after: true, dependencies_installed: false, remote_executed: false,
      log: { path: rel(recheckPrefix + '.jsonl'), sha256: hash(ordinaryLog) },
      stderr: { path: rel(recheckPrefix + '.stderr.txt'), sha256: hash('') },
      runner_sha256: hash(read('docs/evidence/d-resources-local-recheck-20261023.mjs')),
    });
    const options = { localRecheckFile: recheckPrefix + '.json' };
    writeJSON(recheckPrefix + '.json', makeSupplement());
    assert.throws(() => reviewResourcesMySQL(prefix + '.json', undefined, options), /unnecessary local recheck/);
    // Explicitly failing/skipped valid JSON cannot be replaced by a passing supplement.
    for (const Action of ['fail', 'skip']) {
      const failed = eventText([...JSON.parse(JSON.stringify(events())), { Action, Package: pkg }]);
      fs.writeFileSync(prefix + '-step-0.jsonl', failed);
      receipt.steps[0].log_sha256 = hash(failed); writeJSON(prefix + '.json', receipt);
      writeJSON(recheckPrefix + '.json', makeSupplement());
      assert.throws(() => reviewResourcesMySQL(prefix + '.json', undefined, options), /failed\/skipped/);
      fs.writeFileSync(prefix + '-step-0.jsonl', failed + '\n{');
      receipt.steps[0].log_sha256 = hash(failed + '\n{'); writeJSON(prefix + '.json', receipt);
      writeJSON(recheckPrefix + '.json', makeSupplement());
      assert.throws(() => reviewResourcesMySQL(prefix + '.json', undefined, options), /failed\/skipped/);
    }
    const damaged = ordinaryLog.replaceAll('１.00', legacyWindows936Name('１.00')) + '\n{';
    fs.writeFileSync(prefix + '-step-0.jsonl', damaged);
    receipt.steps[0].log_sha256 = hash(damaged); writeJSON(prefix + '.json', receipt);
    writeJSON(recheckPrefix + '.json', makeSupplement());
    assert.throws(() => reviewResourcesMySQL(prefix + '.json'), SyntaxError);
    const supplemented = reviewResourcesMySQL(prefix + '.json', undefined, options);
    assert.equal(supplemented.original_local_step0_valid_json, false);
    assert.equal(supplemented.local_step0_rechecked_same_inputs, true);
    assert.equal(supplemented.artifacts.length, 12);
    for (const mutate of [
      r => { r.parent_receipt.sha256 = binary; }, r => { r.source_manifest.sha256 = binary; },
      r => { r.inputs.pop(); }, r => { r.command.push('-run', 'OneTest'); },
      r => { r.environment.GOPROXY = 'direct'; }, r => { r.exit_code = 1; },
      r => { r.owner_removed = false; }, r => { r.source_verified_before_and_after = false; },
      r => { r.log.sha256 = binary; }, r => { r.dependencies_installed = true; },
      r => { r.runner_sha256 = binary; },
    ]) {
      const invalid = structuredClone(makeSupplement()); mutate(invalid); writeJSON(recheckPrefix + '.json', invalid);
      assert.throws(() => reviewLocalRecheck(recheckPrefix + '.json', prefix + '.json', manifest, []));
    }
    fs.appendFileSync(prefix + '-step-0.jsonl', '\n');
    assert.throws(() => reviewResourcesMySQL(prefix + '.json'), /native step log altered/);
  } finally {
    assert.equal(path.dirname(scratch), path.join(root, 'docs/evidence'));
    assert.ok(path.basename(scratch).startsWith('.tmp-d-receiver-unit-'));
    assert.equal(fs.lstatSync(scratch).isSymbolicLink(), false);
    assert.equal(fs.readFileSync(path.join(scratch, 'owner.txt'), 'utf8'), marker);
    fs.rmSync(scratch, { recursive: true, force: false });
    assert.equal(fs.existsSync(scratch), false);
  }
});
